def marcar_ausencias_existentes_aprobadas(apps, schema_editor):
    """Las ausencias anteriores las registró el oficial directamente: quedan aprobadas."""
    AusenciaLicencia = apps.get_model('inicio', 'AusenciaLicencia')
    AusenciaLicencia.objects.all().update(estado='APROBADA')


def vincular_estudiantes_con_usuarios(apps, schema_editor):
    """Asocia cada estudiante con la cuenta que creó Estudiante.save():
    username = CI, o el primer nombre en minúsculas si no tiene CI."""
    Estudiante = apps.get_model('inicio', 'Estudiante')
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    usados = set()
    for est in Estudiante.objects.filter(usuario__isnull=True):
        user = None
        if est.ci and est.ci.strip():
            user = User.objects.filter(username=est.ci.strip()).first()
        elif est.nombres.strip():
            user = User.objects.filter(
                username=est.nombres.strip().split()[0].lower(),
                last_name=est.apellidos,
            ).first()
        if user and user.id not in usados:
            usados.add(user.id)
            est.usuario = user
            est.save(update_fields=['usuario'])


